cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Get all direct flights (stops=0) from SEA to SAN that include 2026-10-01 in their dates
const flights = db.prepare(\"SELECT * FROM flights WHERE origin = 'SEA' AND destination = 'SAN' AND stops = 0 AND source_skill = 'tau2Airline'\").all();
const results = flights.filter(f => {
  const dates = JSON.parse(f.dates_json);
  return dates['2026-10-01'] && dates['2026-10-01'].status === 'available';
}).map(f => {
  const dates = JSON.parse(f.dates_json);
  const dateInfo = dates['2026-10-01'];
  return {
    flight_id: f.flight_id,
    origin: f.origin,
    destination: f.destination,
    departure_time: f.departure_time,
    arrival_time: f.arrival_time,
    status: dateInfo.status,
    prices: dateInfo.prices,
    available_seats: dateInfo.available_seats
  };
});
console.log(JSON.stringify(results, null, 2));
"

